script:
paragon_beholder_category = {
	desc = paragon_beholder_category_desc
	picture = GFX_evt_ship_in_orbit_3
	level = 2

	spawn_chance = {
		modifier = {
			add = 3
			has_paragon_dlc = yes
			has_planet_flag = pre_sapient_planet
			NOT = { has_carrier_flag = missing_scientist_planet }
		}
		modifier = {
			factor = 0
			from.owner = { is_gestalt = yes }
		}
	}

	max_once_global = yes

	on_spawn = {
		prevent_anomaly = yes
		weighted_random_owned_pop_group = {
			limit = {
				is_sapient = no
			}
			species = {
				save_global_event_target_as = beholder_presapients
			}
		}
		every_owned_pop_group = {
			limit = {
				is_sapient = no
			}
			add_psionic_trait = yes
		}
	}

	on_success = paragon.3
}
